// fonte: site/pages/jogo/cenarios-de-teste.html
// texto visível: Cenários de Teste ZombiAdA Cenários de teste · ZombiAdA Cada cenário é um lugar pronto no jogo. Abra pelo modo livre (tecla M , grupo Cenários de teste), compare com a prévia e dê o veredito. Os critérios trazem a checagem automática que eu rodo antes de publicar. Carregando… Os cenários aparecem aqui assim que a página conecta ao servidor.

// ===== script 0 (812 KB)

const ST = {pendente:"Pendente", aprovado:"Aprovado", ajustar:"Ajustar", reprovado:"Reprovado"};
const S = {cens:[], filtro:"todos", db:null, user:null, nomes:{}, rascunho:{}};
const $ = s => document.querySelector(s);
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
let tT; function toast(m){const t=$("#toast");t.textContent=m;t.hidden=false;clearTimeout(tT);tT=setTimeout(()=>t.hidden=true,2200)}
const quando = ms => { try { return new Date(ms).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"}) } catch(e){ return "" } };
const stOf = c => ST[c.status] ? c.status : "pendente";

function resumo(){
  const n={todos:S.cens.length}; for(const k in ST) n[k]=0; S.cens.forEach(c=>n[stOf(c)]++);
  $("#resumo").innerHTML=[["todos","Todos"],...Object.entries(ST)].map(([k,l])=>`<button class="chip" data-f="${k}" aria-pressed="${S.filtro===k}">${l} <span class="n">${n[k]}</span></button>`).join("");
}
function auto(c){
  const cr=c.criterios||[], a=c.auto||{};
  if(!cr.length) return "";
  return `<div><p class="rot">Critérios${c.autoAt?` · checado ${quando(c.autoAt)}`:""}</p><table>${cr.map(k=>{const r=a[k]||{};const cls=r.ok===true?"s":r.ok===false?"n":"q";const sym=r.ok===true?"✓":r.ok===false?"✗":"·";return `<tr><td class="r ${cls}" aria-label="${r.ok===true?"passou":r.ok===false?"falhou":"sem checagem"}">${sym}</td><td>${esc(k)}${r.nota?`<span class="obs">${esc(r.nota)}</span>`:""}</td></tr>`}).join("")}</table></div>`;
}
function foto(u,leg){ return `<figure>${u?`<img src="${esc(u)}" alt="${esc(leg)}" loading="lazy">`:`<div class="vazio">${esc(leg)}: captura ainda não feita</div>`}<figcaption>${esc(leg)}</figcaption></figure>`; }
function render(){
  const ae=document.activeElement, aid=ae&&ae.id, av=ae&&ae.value;
  resumo();
  const lista=S.cens.filter(c=>S.filtro==="todos"||stOf(c)===S.filtro).sort((a,b)=>(a.ordem||0)-(b.ordem||0));
  if(!S.cens.length){$("#lista").innerHTML=`<p class="vaziopag">${S.db?"Nenhum cenário cadastrado ainda. Eu cadastro os cenários e as capturas; você só dá o veredito.":"Sem conexão com o servidor: os cenários não puderam ser carregados."}</p>`;return}
  let g=null, h="";
  for(const c of lista){
    if(c.grupo!==g){g=c.grupo;h+=`<p class="grupo">${esc(g)}</p>`}
    const st=stOf(c), quem=c.statusBy?(S.nomes[c.statusBy]||"Alguém"):"";
    const nota = S.rascunho[c.id] ?? c.nota ?? "";
    h+=`<section class="cen" id="${esc(c.id)}">
      <div class="cen-top"><div><h2><code>${esc(c.id)}</code>${esc(c.nome)}</h2><p class="como">${c.como?esc(c.como).replace(/\[(.+?)\]/g,"<kbd>$1</kbd>"):""}</p></div><span class="pill ${st}">${ST[st]}</span></div>
      <div class="cen-corpo">
        <div class="fotos">${foto(c.prev,"Prévia")}${foto(c.jogo,"Jogo, altura do jogador")}${(c.extras||[]).map(e=>foto(e.u,e.t)).join("")}</div>
        <div class="lado">
          ${c.olhar?`<div><p class="rot">O que olhar</p><p style="margin:0">${esc(c.olhar)}</p></div>`:""}
          ${auto(c)}
          <div><p class="rot">Seu veredito</p><div class="veredito">${["aprovado","ajustar","reprovado"].map(v=>`<button type="button" data-v="${v}" data-c="${esc(c.id)}" aria-pressed="${st===v}">${ST[v]}</button>`).join("")}</div></div>
          <div><label class="rot" for="nota-${esc(c.id)}">O que ajustar</label><textarea id="nota-${esc(c.id)}" data-c="${esc(c.id)}" placeholder="Ex.: janela pequena demais, gaveta abre muito rápido">${esc(nota)}</textarea>
          <p class="meta">${c.statusAt?`${quem?esc(quem)+" · ":""}${quando(c.statusAt)}`:"Ainda sem veredito"} · a nota salva quando você sai do campo</p></div>
        </div>
      </div></section>`;
  }
  $("#lista").innerHTML=h||`<p class="vaziopag">Nenhum cenário neste filtro.</p>`;
  if(aid){const el=document.getElementById(aid); if(el){el.value=av; el.focus()}}
}
let salvar = async function(id,campos){
  if(!S.db){toast("Sem conexão: não deu para salvar.");return}
  try{ const me=S.user?await S.user.id():""; await S.db.collection("cenarios").doc(id).update({...campos,statusBy:me||"",statusAt:Date.now()}); toast("Salvo") }
  catch(e){ toast(e&&e.code==="invalid_argument"?"Você só pode ver esta página.":"Não deu para salvar agora. Tente de novo.") }
}
document.addEventListener("click",e=>{
  const f=e.target.closest("[data-f]"); if(f){S.filtro=f.dataset.f;render();return}
  const v=e.target.closest("button[data-v]"); if(v){salvar(v.dataset.c,{status:v.dataset.v})}
});
document.addEventListener("input",e=>{ if(e.target.matches("textarea[data-c]")) S.rascunho[e.target.dataset.c]=e.target.value; });
document.addEventListener("change",e=>{ if(e.target.matches("textarea[data-c]")){ const id=e.target.dataset.c; salvar(id,{nota:e.target.value.trim()}).then(()=>{delete S.rascunho[id]}) } });
async function nomes(){ if(!S.user) return; const ids=[...new Set(S.cens.map(c=>c.statusBy).filter(Boolean))]; if(!ids.length) return; try{const p=await S.user.profiles(ids); ids.forEach(i=>S.nomes[i]=(p[i]&&p[i].name)||"Alguém"); render()}catch(e){} }
