const lerLS=()=>{try{return JSON.parse(localStorage.getItem(LS)||'{}')}catch(e){return {}}};
function aplicar(){const v=lerLS();S.cens=DADOS.map(c=>({...c,...(v[c.id]||{})}));render()}
S.db=true;
salvar=async function(id,campos){const v=lerLS();v[id]={...(v[id]||{}),...campos,statusAt:Date.now()};try{localStorage.setItem(LS,JSON.stringify(v));toast('Salvo neste computador')}catch(e){toast('O navegador não deixou salvar aqui')}aplicar()};
function exportar(){const v=lerLS(),out={};DADOS.forEach(c=>{const x=v[c.id]||{};out[c.id]={status:x.status||c.status||'pendente',nota:x.nota??c.nota??'',statusAt:x.statusAt||c.statusAt||0}});
  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({pagina:'cenarios-zombiada',em:Date.now(),vereditos:out},null,1)],{type:'application/json'}));a.download='vereditos-cenarios.json';a.click();toast('Arquivo baixado: leve para a página online em Importar')}
function importar(f){const r=new FileReader();r.onload=()=>{try{const j=JSON.parse(r.result),v=lerLS();let n=0;for(const[id,x]of Object.entries(j.vereditos||{})){if(!DADOS.find(c=>c.id===id))continue;v[id]={status:x.status,nota:x.nota,statusAt:x.statusAt||Date.now()};n++}localStorage.setItem(LS,JSON.stringify(v));aplicar();toast(n+' vereditos importados')}catch(e){toast('Arquivo inválido')}};r.readAsText(f)}
$('#modo').innerHTML='Cópia local<br><b>vereditos salvos neste computador</b><div style="display:flex;gap:6px;margin-top:6px;justify-content:flex-end"><button type="button" id="exp" class="chip">Exportar</button><label class="chip" style="cursor:pointer">Importar<input type="file" id="imp" accept=".json,application/json" hidden></label></div><small>Fotos de 22/10 16:40</small>';
$('#exp').onclick=exportar; $('#imp').onchange=e=>{if(e.target.files[0])importar(e.target.files[0])};
aplicar();
